import{_ as o,c as t,o as a,ag as r}from"./chunks/framework.DuVOYUUM.js";const m=JSON.parse('{"title":"Design","description":"","frontmatter":{},"headers":[],"relativePath":"projects/minibot/design.md","filePath":"projects/minibot/design.md","lastUpdated":1790647345000}'),n={name:"projects/minibot/design.md"};function i(s,e,c,d,l,h){return a(),t("div",null,e[0]||(e[0]=[r('<h1 id="design" tabindex="-1">Design <a class="header-anchor" href="#design" aria-label="Permalink to &quot;Design&quot;">​</a></h1><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>The design of Minibot was based around a previous robot, Ranibot. As it was meant to be a introductory project to new members.</p><h3 id="electrical-components" tabindex="-1">Electrical Components <a class="header-anchor" href="#electrical-components" aria-label="Permalink to &quot;Electrical Components&quot;">​</a></h3><p>The minibot consists of four MD10C R3 10 Amp DC Motor Controllers, each attached to an Geartisan 150RPM Gear Motor (ZGA37RG31.6i). A central Arduino/ESP32 interfaces with the motor controllers. The motor controllers connect to the Arudino through the PWM Pins for speed control, and Digital Pins for direction control. Each motor controller requires that it be connected to logical ground.</p><p><a href="https://images-na.ssl-images-amazon.com/images/I/A1TemgvjKjL.pdf" target="_blank" rel="noreferrer">Datasheet For MD10CR3</a><a href="https://www.mpja.com/download/32203-32206MDMech.pdf" target="_blank" rel="noreferrer">Datasheet for Geartisan 150RPM Motor</a></p><h3 id="software-components" tabindex="-1">Software Components <a class="header-anchor" href="#software-components" aria-label="Permalink to &quot;Software Components&quot;">​</a></h3><p>Operating the minibot requires uploading code to the central device that connects to the motor controllers. The steps to upload code changes depending on which kind of device is connected:</p><h4 id="arduino" tabindex="-1">Arduino <a class="header-anchor" href="#arduino" aria-label="Permalink to &quot;Arduino&quot;">​</a></h4><p>Arduino code is typically distributed through a Sketch file to be used in the Arduino IDE. Example code for such a program can be found <a href="https://github.com/oaklandrobotics/minibot23/tree/main" target="_blank" rel="noreferrer">here</a>.</p><h4 id="esp32" tabindex="-1">ESP32 <a class="header-anchor" href="#esp32" aria-label="Permalink to &quot;ESP32&quot;">​</a></h4><p>Like the Arudino, the Arduino IDE can be used to upload code to the ESP32. Example code for such a program can be found here.</p>',12)]))}const u=o(n,[["render",i]]);export{m as __pageData,u as default};
